#include <bits/stdc++.h>
using namespace std;

class LazySum {
    int n;
    vector<long long> sum, set, pending_add;
    vector<bool> has_set;
    void build(int node, int l, int r, const vector<long long>& a) {
        if (l == r) {
            sum[node] = a[l];
            return;
        }
        int mid = l + (r - l) / 2;
        build(node * 2, l, mid, a);
        build(node * 2 + 1, mid + 1, r, a);
        sum[node] = sum[node * 2] + sum[node * 2 + 1];
    }

void apply_set(int node, int length, long long value) {
    sum[node] = value * length;
    has_set[node] = true;
    set[node] = value;
    pending_add[node] = 0;
}
void apply_add(int node, int length, long long value) {
    sum[node] += value * length;
    pending_add[node] += value;
}
void push(int node, int l, int r) {
    if (l == r) {
        return;
    }
    int mid = l + (r - l) / 2;
    if (has_set[node]) {
        apply_set(node * 2, mid - l + 1, set[node]);
        apply_set(node * 2 + 1, r - mid, set[node]);
        has_set[node] = false;
    }
    if (pending_add[node] != 0) {
        apply_add(node * 2, mid - l + 1, pending_add[node]);
        apply_add(node * 2 + 1, r - mid, pending_add[node]);
        pending_add[node] = 0;
    }
}

void update(int node, int l, int r, int ql, int qr,
            long long value, bool assignment) {
    if (qr < l || r < ql) {
        return;
    }
    if (ql <= l && r <= qr) {
        if (assignment) {
            apply_set(node, r - l + 1, value);
        } else {
            apply_add(node, r - l + 1, value);
        }
        return;
    }
    push(node, l, r);
    int mid = l + (r - l) / 2;
    update(node * 2, l, mid, ql, qr, value, assignment);
    update(node * 2 + 1, mid + 1, r, ql, qr, value, assignment);
    sum[node] = sum[node * 2] + sum[node * 2 + 1];
}

    long long query(int node, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) {
            return 0;
        }
        if (ql <= l && r <= qr) {
            return sum[node];
        }
        push(node, l, r);
        int mid = l + (r - l) / 2;
        return query(node * 2, l, mid, ql, qr)
             + query(node * 2 + 1, mid + 1, r, ql, qr);
    }
public:
    explicit LazySum(const vector<long long>& a)
        : n(static_cast<int>(a.size()) - 1), sum(4 * n),
          set(4 * n), pending_add(4 * n), has_set(4 * n) {
        build(1, 1, n, a);
    }
    void add(int l, int r, long long value) {
        update(1, 1, n, l, r, value, false);
    }
    void assign(int l, int r, long long value) {
        update(1, 1, n, l, r, value, true);
    }
    long long range_sum(int l, int r) {
        return query(1, 1, n, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    LazySum tree(a);
    for (int query = 0; query < q; ++query) {
        int type, l, r;
        cin >> type >> l >> r;
        if (type == 3) {
            cout << tree.range_sum(l, r) << '\n';
        } else {
            long long value;
            cin >> value;
            if (type == 1) {
                tree.add(l, r, value);
            } else {
                tree.assign(l, r, value);
            }
        }
    }
}

